<?php
namespace App\Controllers\Customer;
final class Auth extends PortalController
{
 public function login(){if(service('customerSession')->user())return redirect()->to(url_to('customer.dashboard'));session()->remove('customer_linking');return $this->renderPortal('auth/login',['pageTitle'=>'Sign in to your property portal','authPage'=>true,'authMode'=>'login']);}
 public function register(){if(service('customerSession')->user())return redirect()->to(url_to('customer.dashboard'));session()->remove('customer_linking');return $this->renderPortal('auth/register',['pageTitle'=>'Connect your property account','authPage'=>true,'authMode'=>'register']);}
 public function link(){session()->set('customer_linking',(int)service('customerSession')->user()['id']);return $this->renderPortal('auth/login',['pageTitle'=>'Verify another ERP identity','authPage'=>true,'authMode'=>'link']);}
 public function verify(){try{$info=service('customerOtp')->info((string)session()->get('customer_challenge_id'),service('customerSession')->binding());}catch(\Throwable $e){return redirect()->to(url_to('customer.login'))->with('customer_auth_error','Verification expired. Please start again.');}return $this->renderPortal('auth/verify_otp',['pageTitle'=>'Verify your mobile number','authPage'=>true,'challenge'=>$info]);}
 public function requestOtp(){return $this->action(function(){$data=$this->input();if(!is_string($data['cnic']??null)||!is_string($data['mobile']??null))throw new \InvalidArgumentException('Enter your CNIC and registered mobile number.');$target=session()->get('customer_linking');if($target!==null&&(!service('customerSession')->user()||(int)service('customerSession')->user()['id']!==(int)$target))throw new \App\Exceptions\CustomerFlowException(401,'Please sign in again.');$info=service('customerOtp')->request($data['cnic'],$data['mobile'],service('customerSession')->binding(),$this->request->getIPAddress(),$target!==null?(int)$target:null);session()->set('customer_challenge_id',$info['id']);return $this->json(['message'=>'If these details match a registered ERP identity, a verification code has been sent.','redirect'=>url_to('customer.verify')],202);});}
 public function verifyOtp(){return $this->action(function(){$data=$this->input();if(!is_string($data['otp']??null))throw new \InvalidArgumentException('Enter the six-digit verification code.');$current=service('customerSession')->user();$result=service('customerOtp')->verify((string)session()->get('customer_challenge_id'),$data['otp'],service('customerSession')->binding(),$this->request->getIPAddress(),$current?(int)$current['id']:null);$resaleEntry=session()->get('customer_resale_entry')===true;service('customerSession')->login($result['customer']);session()->set('customer_source_warnings',$result['portfolio']['unavailable']);return $this->json(['redirect'=>url_to($resaleEntry?'customer.properties':'customer.dashboard'),'message'=>'Mobile verified. Your property account is ready.']);});}
 public function resendOtp(){return $this->action(function(){$info=service('customerOtp')->resend((string)session()->get('customer_challenge_id'),service('customerSession')->binding(),$this->request->getIPAddress());return $this->json(['message'=>'If your identity is verified, a new code has been sent.','challenge'=>$info]);});}
 public function logout(){service('customerSession')->logout();return redirect()->to(url_to('customer.login'));}
}
